INSERT INTO changelog (title, body, created_at) VALUES
('Джері пише в групи клієнтів і робить презентації',
'На пряме прохання Саші («відправ клієнту звіт за тиждень по рекламі презентацією») Джері збирає цифри, робить PDF-презентацію (A4 горизонтально, темна фірмова: титульний слайд, картки-цифри, списки, таблиці) і надсилає в Telegram-групу клієнта з ввічливим підписом. Сам у групи не пише ніколи. Надіслане видно в чаті картки (від «Джері»). Вимикається в Налаштування → «Можливості» → «Писати в групи клієнтів». make_pdf: format document (документ) або slides (презентація).',
'2026-10-30 22:40:00');
